-- Accounts (specification 6, 7.2). "user" is a reserved word, so the table is app_user.
-- Ids are UUID version 7, generated by the application.
CREATE TABLE app_user (
    id            uuid        PRIMARY KEY,
    email         text        NOT NULL,
    display_name  text        NOT NULL,
    password_hash text        NOT NULL,
    role          text        NOT NULL,
    enabled       boolean     NOT NULL,
    last_login_at timestamptz,
    created_at    timestamptz NOT NULL,
    updated_at    timestamptz NOT NULL,
    CONSTRAINT app_user_email_key UNIQUE (email),
    -- AUTH-10: the unique key only works if every email is stored in one form.
    CONSTRAINT app_user_email_normalized CHECK (email = lower(btrim(email))),
    CONSTRAINT app_user_role_check CHECK (role IN ('ADMIN', 'FACULTY', 'STUDENT'))
);
